// Independent PLAY-04 re-check: run each real-time clock test that failed in RUN-20261016-020 inside a window
// free of host calendar steps. A sampler tracks (wall - monotonic); each test starts right after an observed
// step and the result records whether another step landed during the test. Unmodified tests, no environment change.
import { spawn } from 'node:child_process';
const offset = () => Date.now() - performance.timeOrigin - performance.now();
const tests = [
  ['tests/clock-live.test.mjs', 'stock live clients complete all opening decisions amid repeated waiting concessions without busy or clock events'],
  ['tests/clock-live.test.mjs', 'live3 busy contention retries the same concession on the same socket without maintenance or duplicate effects'],
  ['tests/clock-process.test.mjs', 'an engine calculation outliving its lease is fenced and durably paused'],
  ['tests/clock-process.test.mjs', 'timed process death before COMMIT preserves clock, receipt and journal atomicity'],
];
const escape = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
async function nextStep(limitMs = 90000) {
  const end = performance.now() + limitMs; let last = offset();
  while (performance.now() < end) { await new Promise(r => setTimeout(r, 50)); const now = offset(); if (Math.abs(now - last) > 1000) return now - last; last = now; }
  return null;
}
const results = [];
for (const [file, name] of tests) {
  const step = await nextStep();
  const before = offset(), t0 = performance.now(); let maxShift = 0;
  const sampler = setInterval(() => { maxShift = Math.max(maxShift, Math.abs(offset() - before)); }, 50);
  let tap = '';
  const code = await new Promise(resolve => {
    const child = spawn('node', ['--test', '--test-concurrency=1', '--test-reporter=tap', '--test-name-pattern=^' + escape(name) + '$', file], { cwd: 'apps/match-service', stdio: ['ignore', 'pipe', 'ignore'] });
    child.stdout.on('data', d => { tap += d; }); child.on('exit', c => resolve(c));
  });
  const count = k => Number((tap.match(new RegExp('^# ' + k + ' (\\d+)', 'm')) || [])[1] ?? NaN);
  clearInterval(sampler);
  results.push({ name, precedingStepMs: step === null ? null : Math.round(step), durationMs: Math.round(performance.now() - t0), stepDuringTestMs: Math.round(maxShift), exitCode: code, pass: count('pass'), fail: count('fail') });
}
console.log(JSON.stringify({ results, allPassed: results.every(r => r.exitCode === 0 && r.pass === 1 && r.fail === 0), anyStepDuringTest: results.some(r => r.stepDuringTestMs > 1000) }, null, 1));
